// Regressions for independently observed defects, using real narrative/collection/HP state.
'use strict';
const assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm');
const {loadP,ROOT}=require('./lib-load'),game=loadP();
game.Meta.reset();
assert.equal(game.Meta.Collect.catalogue().filter(x=>x.kind==='badge').length,17);
let page,finish,completed=0;
game.Comic={page(ids,done){page=ids;finish=done;}};
const before=JSON.parse(JSON.stringify(game.Meta.state()));
game.Story.play(1,'end',()=>completed++,{levelIndex:1});
assert.equal(page,'l1_outro');assert(!game.Meta.state().collection['page:l1_outro']);
finish(false);assert.equal(completed,1);
assert(game.Meta.Save.read().collection['page:l1_outro'],'Viewed page survives save reload');
assert.deepEqual(game.Meta.state().stars,before.stars);assert.equal(game.Meta.state().coins,before.coins);
const archived=JSON.stringify(game.Meta.state());
game.Comic.page('l1_outro',()=>{});finish(false);
assert.equal(JSON.stringify(game.Meta.state()),archived,'Memory replay cannot settle a reward or change a fact');
game.Meta.state().flags.kaanMarketCover=true;
game.Story.play(25,'end',()=>{},{});assert.equal(page,'captain_end_market');finish(true);
assert(game.Meta.Save.read().collection['page:captain_end_market']);
assert(!game.Meta.state().collection['page:captain_end_covered']);
assert(!game.Meta.state().collection['page:captain_end'],'Unseen relationship variants remain locked');
for(const file of ['health-feedback','boss-acting','boss-joints','hero-contact'])
 vm.runInThisContext(fs.readFileSync(ROOT+'/js/view/'+file+'.js','utf8'),{filename:file});
const s=game.createSim(42,{levelIndex:3});game.startPlay(s);s.hero.hp=82;
game.HealthFeedback.reset(s);
game.HealthFeedback.event({type:'pickup',kind:'simit',healed:5,hp:85},s);
game.HealthFeedback.event({type:'heroHit',dmg:3,beforeHp:85,hp:82},s);
game.HealthFeedback.update(s,.01);
assert.equal(game.HealthFeedback.state().restored.from,80);
assert.equal(game.HealthFeedback.state().restored.to,85);
assert.equal(game.HealthFeedback.state().hp,82);
assert(game.HealthFeedback.state().heal>0&&game.HealthFeedback.state().hurt>0);
const e={bossPreset:'bigFisher',age:0,walk:0,ai:{m:'windup',act:'bridgeCast'},windup:.8};
assert.equal(game.BossActing.pose(e,{}),3);
e.ai.m='switchRecover';e.age=1;assert.equal(game.BossActing.pose(e,{}),4);
e.age=1.4;assert.equal(game.BossActing.pose(e,{}),5);
e.ai.m='defeat';assert.equal(game.BossActing.pose(e,{}),7);
for(const d of Object.values(game.CFG.bossActing)) {
 assert.equal(d.frames.length,8);assert(d.heightPx>100);
 assert(d.frames.every(f=>f[4]>0&&f[5]>0),'Each pose has a measured ground anchor, never a per-pose height rescale');
}
const torso={sw:80,sh:160},hands=[[8,107],[70,107]];
const o={attackId:'chainsaw',attackProgress:.4,attackHand:1,attackStance:{aim:0},motion:{}};
game.HeroContact.apply(torso,'side',0,o,1,hands);
assert(o.motion.workTargets.left&&o.motion.workTargets.right);
const quiet={motion:{}};game.HeroContact.apply(torso,'side',0,quiet,1,hands);
assert.equal(quiet.motion.workTargets,undefined,'Ordinary running remains untouched');
const route=game.createSim(42,{levelIndex:15,tramRhythm:true});game.startPlay(route);
route.hero.y=7;game.Levels.step(route,0);
assert.equal(route.drops.filter(d=>d.kind==='chest').length,1,'The existing first supply is reachable in the entry room');
route.hero.y=35;game.Levels.step(route,0);
assert.equal(route.drops.filter(d=>d.kind==='chest').length,1,'Crossing B cannot duplicate the moved supply');
const market=game.createSim(42,{levelIndex:24,tramRhythm:true});game.startPlay(market);
const m=market.milestone,K=game.CFG.levels.eminonuMilestones.signal.cart;
m.point.progress=1;market.hero.x=-4;market.hero.y=m.y+3;
const target=game.Combat.spawnEnemy(market,'walker',0,m.y-K.yBack,{state:'active'});target.hp=target.maxHp=300;
const initial=target.hp;game.EminonuTrial.ready(market,m,2.5);
assert(target.hp<initial,'A real crossing trolley damages an ordinary enemy in its swept path');
const hitHp=target.hp;game.EminonuTrial.ready(market,m,1.1);assert.equal(target.hp,hitHp,'One pass has exactly one hit per target');
assert.equal(market.hero.hp,market.hero.maxHp,'The safe side remains safe');
const keeper=game.Bosses.spawn(market,'brute',2,m.y+4,{preset:'bellkeeper',hoodIdx:1,nameKey:'boss.bellkeeper'});
game.Bosses.exposeFor(market,keeper,0);keeper.ai.m='walk';keeper.ai.cd=1;
game.Bosses.think(market,keeper,1/60);assert.equal(keeper.dvx,0);assert.equal(keeper.dvy,0);
const {useActiveSkills}=require('./lib-bot-play');
const lane=game.createSim(42,{levelIndex:3,tramRhythm:true});game.startPlay(lane);lane.hero.x=1;lane.hero.y=2;
lane.enemyTele=[{kind:'lane',x:0,y:0,dx:0,dy:1,w:3,len:8,T:1,t:.8}];
const dash=useActiveSkills(game,lane,{x:0,y:1},(x,y)=>{const d=Math.hypot(x,y)||1;return{x:x/d,y:y/d};});
assert(dash.dash&&dash.x>0&&Math.abs(dash.y)<.01,'Audit dodge moves away from the real lane in world coordinates');
console.log('Audit8 identity/archive/replay, catalogue, event-time HP, boss contact and running preservation checks pass.');
for(const n of [13,25])for(const seed of [1,3,42,97]){
 const parked=game.createSim(seed,{levelIndex:n,tramRhythm:true});
 const car=parked.env.recs.find(r=>game.Env.isCar(r.kind));assert(car,'Actual illustrated car is available in L'+n);
 assert(game.Env.pathOpen(parked),'Parked car preserves a traversable route');
 assert(game.Weapons6.terrainAt(parked,car.x,car.y).includes('car'));
 assert(!game.Env.streetSized(car.b),'Car is larger than the portable-object limit');
}
const food=game.createSim(42,{tramRhythm:true}),cart=food.props.carts[0];
assert(!game.Weapons6.terrainAt(food,cart.x,cart.y).includes('car'),'A simit cart cannot impersonate a car');
const intention=game.createSim(42,{levelIndex:12,tramRhythm:true});game.startPlay(intention);
intention.hero.weapons={knife:4,chainsaw:1};intention.recipeFocus='knife';intention.pendingLevels=1;intention.cardPicks=3;
game.Progression.choose(intention,game.Progression.cardFor(intention,'w:chainsaw'));
assert.equal(intention.recipeFocus,'knife','A casual secondary upgrade preserves the committed plan');
assert(!game.Progression.setBuildPlan(intention,'canister'),'A plan never grants an unowned weapon');
const oldRanks=JSON.stringify(intention.hero.weapons),oldRerolls=intention.rerolls;
assert(game.Progression.setBuildPlan(intention,'chainsaw'));
assert.equal(intention.recipeFocus,'chainsaw','An explicit owned-weapon plan is respected');
assert.equal(JSON.stringify(intention.hero.weapons),oldRanks);assert.equal(intention.rerolls,oldRerolls);
game.Progression.choose(intention,{id:'w:knife',item:'knife',next:5},true);
assert.equal(intention.recipeFocus,'chainsaw','An automatic chest cannot overwrite the chosen plan');
const vanished=game.createSim(43,{levelIndex:22,tramRhythm:true});game.startPlay(vanished);
const missing=vanished.streetSite.prop;missing.alive=false;
Object.assign(vanished.hero,{x:missing.x,y:missing.b.rc.yMin-game.CFG.hero.radius-.1});
assert.equal(require('./lib-bot-play').auditChoiceInput(game,vanished,{bestT:0},{choice:'right'},(x,y)=>({x,y})),null,
 'The audit driver abandons a destroyed object instead of standing forever at its old grip');
